+// Filtering an indexed (paletted) PNG must not clamp the result to the
+// source palette. See issue 12543.
+func TestFilterPalettedPNGIssue12543(t *testing.T) {
+	t.Parallel()
+
+	files := `
+-- hugo.toml --
+-- assets/gohugoio8.png --
+sourcefilename: ../testdata/gohugoio8.png
+-- assets/sunset.jpg --
+sourcefilename: ../testdata/sunset.jpg
+-- layouts/home.html --
+{{ $bg := resources.Get "gohugoio8.png" }}
+{{ $sunset := (resources.Get "sunset.jpg").Resize "x100 png" }}
+{{ $textOpts := dict "color" "#ff0060" "size" 60 "x" 10 "y" 10 }}
+{{ with $bg.Resize "300x" | resources.Copy "images/resized.png" }}{{ .Publish }}{{ end }}
+{{ with $sunset | resources.Copy "images/sunset.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter (images.Overlay $sunset 20 30) | resources.Copy "images/overlay.png" }}{{ .Publish }}{{ end }}
+{{ with ($bg.Resize "300x").Filter (images.Overlay $sunset 20 30) | resources.Copy "images/overlay-resized.png" }}{{ .Publish }}{{ end }}
+{{ with $bg.Filter (images.Text "Hugo" $textOpts) | resources.Copy "images/text.png" }}{{ .Publish }}{{ end }}
+`
+
+	b := hugolib.Test(t, files)
+
+	decode := func(filename string) image.Image {
+		f, err := b.H.Fs.PublishDir.Open(filename)
+		b.Assert(err, qt.IsNil)
+		defer f.Close()
+		img, err := png.Decode(f)
+		b.Assert(err, qt.IsNil)
+		return img
+	}
+
+	toRGBA := func(c color.Color) color.RGBA {
+		return color.RGBAModel.Convert(c).(color.RGBA)
+	}
+
+	// Resizing an indexed PNG still preserves the source palette.
+	_, isPaletted := decode("images/resized.png").(*image.Paletted)
+	b.Assert(isPaletted, qt.IsTrue)
+
+	// The overlay must be drawn with its own colors, not the background's palette.
+	sunset := decode("images/sunset.png")
+	for _, filename := range []string{"images/overlay.png", "images/overlay-resized.png"} {
+		composite := decode(filename)
+		_, isPaletted := composite.(*image.Paletted)
+		b.Assert(isPaletted, qt.IsFalse, qt.Commentf(filename))
+		sb := sunset.Bounds()
+		for y := sb.Min.Y; y < sb.Max.Y; y += 7 {
+			for x := sb.Min.X; x < sb.Max.X; x += 7 {
+				b.Assert(toRGBA(composite.At(x+20, y+30)), qt.Equals, toRGBA(sunset.At(x, y)), qt.Commentf("%s at %d,%d", filename, x, y))
+			}
+		}
+	}
+
+	// The text color must be preserved.
+	text := decode("images/text.png")
+	_, isPaletted = text.(*image.Paletted)
+	b.Assert(isPaletted, qt.IsFalse)
+	textColor := color.RGBA{R: 0xff, G: 0x00, B: 0x60, A: 0xff}
+	var found bool
