+// formatDuration formats d with two decimal places and a unit suffix
+// padded to a fixed width, so that decimal points align when the
+// values are right-aligned in a table column.
+func formatDuration(d time.Duration) string {
+	units := []struct {
+		suffix string
+		div    time.Duration
+	}{
+		{"ns", time.Nanosecond},
+		{"µs", time.Microsecond},
+		{"ms", time.Millisecond},
+		{"s ", time.Second},
+	}
+	var s string
+	for _, u := range units {
+		s = strconv.FormatFloat(float64(d)/float64(u.div), 'f', 2, 64) + u.suffix
+		// Use the next unit if the rounded value reaches 1000,
+		// e.g. 999.996µs is printed as 1.00ms, not 1000.00µs.
+		if v, _ := strconv.ParseFloat(s[:len(s)-len(u.suffix)], 64); math.Abs(v) < 1000 {
+			break
+		}
+	}
+	return s
+}
