+					files = append(files, filepath.ToSlash(strings.TrimPrefix(path, string(filepath.Separator))))
+				}
+				return nil
+			}), qt.IsNil)
+
+			if caseInsensitive {
+				c.Assert(files, qt.DeepEquals, []string{"MyBundle/cover.jpg"})
+			} else {
+				c.Assert(files, qt.DeepEquals, []string{"mybundle/cover.jpg"})
+			}
+			c.Assert(cache.GetString(filepath.FromSlash("mybundle/cover.jpg")), qt.Not(qt.Equals), "")
+		})
