+
+// caseInsensitiveFs resolves names case-insensitively against existing
+// entries, preserving the case of existing entries, like e.g. macOS APFS.
+type caseInsensitiveFs struct {
+	afero.Fs
+}
+
+func (fs caseInsensitiveFs) resolve(name string) string {
+	name = filepath.Clean(name)
+	parts := strings.Split(name, string(filepath.Separator))
+	resolved := parts[0]
+	for i, part := range parts[1:] {
+		dir := resolved
+		if dir == "" {
+			dir = string(filepath.Separator)
+		}
+		fis, err := afero.ReadDir(fs.Fs, dir)
+		if err != nil {
+			return filepath.Join(append([]string{dir}, parts[i+1:]...)...)
+		}
+		for _, fi := range fis {
+			if strings.EqualFold(fi.Name(), part) {
+				part = fi.Name()
+				break
+			}
+		}
+		resolved = filepath.Join(dir, part)
+	}
+	return resolved
+}
+
+func (fs caseInsensitiveFs) Create(name string) (afero.File, error) {
+	return fs.Fs.Create(fs.resolve(name))
+}
+
+func (fs caseInsensitiveFs) Mkdir(name string, perm os.FileMode) error {
+	return fs.Fs.Mkdir(fs.resolve(name), perm)
+}
+
+func (fs caseInsensitiveFs) MkdirAll(path string, perm os.FileMode) error {
+	return fs.Fs.MkdirAll(fs.resolve(path), perm)
+}
+
+func (fs caseInsensitiveFs) Open(name string) (afero.File, error) {
+	return fs.Fs.Open(fs.resolve(name))
+}
+
+func (fs caseInsensitiveFs) OpenFile(name string, flag int, perm os.FileMode) (afero.File, error) {
+	return fs.Fs.OpenFile(fs.resolve(name), flag, perm)
+}
+
+func (fs caseInsensitiveFs) Remove(name string) error {
+	return fs.Fs.Remove(fs.resolve(name))
+}
+
+func (fs caseInsensitiveFs) RemoveAll(path string) error {
+	return fs.Fs.RemoveAll(fs.resolve(path))
+}
+
+func (fs caseInsensitiveFs) Rename(oldname, newname string) error {
+	return fs.Fs.Rename(fs.resolve(oldname), fs.resolve(newname))
+}
+
+func (fs caseInsensitiveFs) Stat(name string) (os.FileInfo, error) {
+	return fs.Fs.Stat(fs.resolve(name))
+}
+
+func (fs caseInsensitiveFs) Chmod(name string, mode os.FileMode) error {
+	return fs.Fs.Chmod(fs.resolve(name), mode)
+}
+
+func (fs caseInsensitiveFs) Chown(name string, uid, gid int) error {
+	return fs.Fs.Chown(fs.resolve(name), uid, gid)
+}
+
+func (fs caseInsensitiveFs) Chtimes(name string, atime, mtime time.Time) error {
