+func TestRelatedFragmentsTokenize(t *testing.T) {
+	t.Parallel()
+
+	filesTemplate := `
+-- hugo.toml --
+baseURL = "http://example.com/"
+disableKinds = ["taxonomy", "term", "RSS", "sitemap", "robotsTXT"]
+[markup.goldmark.parser]
+autoDefinitionTermID = true
+[related]
+  includeNewer = true
+  threshold = 20
+  toLower = TOLOWER
+[[related.indices]]
+  name = 'fragments'
+  type = 'fragments'
+  applyFilter = true
+  tokenize = TOKENIZE
+  weight = 100
+-- content/p1.md --
+---
+title: p1
+---
+## Installing Hugo on Linux
+
+Some text.
+
+Linux kernel
+: A definition.
+-- content/p2.md --
+---
+title: p2
+---
+## Hugo themes overview
+
+## Unrelated section
+-- content/p3.md --
+---
+title: p3
+---
+## Using ` + "`linux`" + ` commands
+
+## Another unrelated section
+-- content/p4.md --
+---
+title: p4
+---
+## Something else
+
+Linux kernel
+: Another definition.
+-- layouts/single.html --
+{{ $related := site.RegularPages.Related . }}
+Related: {{ range $related }}{{ .Title }}: {{ range .HeadingsFiltered }}{{ .Title }}|{{ .ID }}|{{ end }}::{{ end }}END
+{{ $q := site.RegularPages.Related (dict "indices" (slice "fragments") "fragments" (slice "Themes overview")) }}
+Query: {{ range $q }}{{ .Title }}: {{ range .HeadingsFiltered }}{{ .ID }}|{{ end }}::{{ end }}END
+`
+
+	files := func(tokenize, toLower bool) string {
+		return strings.NewReplacer("TOKENIZE", fmt.Sprint(tokenize), "TOLOWER", fmt.Sprint(toLower)).Replace(filesTemplate)
+	}
+
+	t.Run("Default", func(t *testing.T) {
+		t.Parallel()
+		b := hugolib.Test(t, files(false, false))
+		// Only exact identifier matches (the definition term).
+		b.AssertFileContent("public/p1/index.html", "Related: p4: ::END", "Query: END")
+		b.AssertFileContent("public/p2/index.html", "Related: END")
+	})
+
+	t.Run("Tokenize", func(t *testing.T) {
+		t.Parallel()
+		b := hugolib.Test(t, files(true, false))
+		// "Hugo" in heading titles of p1 and p2, definition term matches p4 exactly.
+		b.AssertFileContent("public/p1/index.html", "Related: ", "p2: Hugo themes overview|hugo-themes-overview|::", "p4: ::")
+		b.AssertFileContent("public/p1/index.html", "! p3:")
+		b.AssertFileContent("public/p2/index.html", "Related: p1: Installing Hugo on Linux|installing-hugo-on-linux|::p3: Another unrelated section|another-unrelated-section|::END")
+		// Unrelated sections share the "unrelated" and "section" words.
+		b.AssertFileContent("public/p3/index.html", "Related: p2: Unrelated section|unrelated-section|::END")
+		// The non-heading identifier is not tokenized, so "kernel" etc. does not match p3.
+		b.AssertFileContent("public/p4/index.html", "Related: p1: ::END")
+		// Query with a multi-word fragment.
+		b.AssertFileContent("public/p1/index.html", "Query: p2: hugo-themes-overview|::END")
+	})
+
+	t.Run("TokenizeToLower", func(t *testing.T) {
+		t.Parallel()
+		b := hugolib.Test(t, files(true, true))
+		// "Linux" in p1 and "linux" (inside code) in p3 now match.
+		b.AssertFileContent("public/p3/index.html", "p1: Installing Hugo on Linux|installing-hugo-on-linux|::", "p2: Unrelated section|unrelated-section|::")
+		b.AssertFileContent("public/p1/index.html", "p3: Using &lt;code&gt;linux&lt;/code&gt; commands|using-linux-commands|::")
+	})
+}
